/**
 * API types. Every request/response shape the backend declares is an alias of
 * `components["schemas"][...]` from ./schema (generated by `npm run gen:api` from docs/openapi.json;
 * `npm run check:api` fails if either is stale). Do not redefine those shapes here.
 *
 * Hand-written below, because OpenAPI cannot express them:
 *  - the SSE `RunEvent` union (server-sent event payloads are not in the OpenAPI document),
 *  - `Rejection` and its `Reason` / `Gate` literals (only appear inside SSE `round` events),
 *  - `GET /api/overheads`, which the backend declares without a response model (schema is `unknown`),
 *  - small narrowing shims (`RunRequest` defaults, `Row`) noted where they occur.
 */
import type { components } from "./schema";

type S = components["schemas"];

export type { components };

// ---- aliases of the generated schema -------------------------------------------------------------
export type Hardware = S["Hardware"];
export type Receipt = S["Receipt"];
export type ReceiptsResponse = S["ReceiptsResponse"];
export type ZkRound = S["ZkRound"];
export type ZkRoundsResponse = S["ZkRoundsResponse"];
export type Vote = S["ConsensusVote"];
export type ConsensusRound = S["ConsensusRound"];
export type ConsensusView = S["ConsensusResponse"];
export type Certificate = S["Certificate"];
export type CertVote = S["CertVote"];
export type CertificateVerifyRequest = S["VerifyRequest"];
export type CertificateVerifyResponse = S["VerifyResponse"];
export type LimitationsResponse = S["LimitationsResponse"];
export type HealthResponse = S["Health"];
export type ScenariosResponse = S["ScenariosResponse"];
export type Scenario = S["Scenario"];
export type RunCreated = S["RunCreated"];

export type ScenarioId = S["Scenario"]["id"];
export type AttackName = NonNullable<S["RunRequest"]["attack"]>;
export type DefenceMode = NonNullable<S["RunRequest"]["defence"]>;
export type Aggregator = S["RunRequest"]["aggregator"];

/** Schema type with the server-side defaults (`aggregator`, `live_zk`) made optional for callers. */
export type RunRequest = Omit<S["RunRequest"], "aggregator" | "live_zk"> &
  Partial<Pick<S["RunRequest"], "aggregator" | "live_zk">>;

/** Schema declares result cells as `unknown`; the UI treats them as JSON scalars (narrowing shim). */
export type Row = Record<string, string | number | boolean | null>;
export type ResultsResponse = Omit<S["ResultsResponse"], "rows"> & { rows: Row[] };

// ---- hand-written: SSE payloads (not in OpenAPI) -------------------------------------------------
export type Reason =
  | "bad_signature"
  | "wrong_round"
  | "norm_bound_exceeded"
  | "bad_proof"
  | "replay"
  | "not_in_quorum"
  | "other";
export type Gate = "signature" | "plaintext_norm_gate" | "zk" | "consensus";
export interface Rejection {
  round: number;
  client: number | null;
  reason: Reason;
  raw_reason: string;
  gate: Gate;
}

export interface ConsensusSummary {
  leader: number;
  votes: number;
  quorum: number;
  finalized: boolean;
}
export interface SeedDone {
  seed: number;
  final_accuracy: number | null;
  diverged_round: number | null;
  convention_note: string | null;
}
export type RunEvent =
  | { type: "queued"; position: number }
  | { type: "started"; seed: number; attack: string; defence: string; aggregator: string; rounds: number }
  | {
      type: "round";
      seed: number;
      round: number;
      accuracy: number | null;
      diverged: boolean;
      accepted: number[];
      accepted_count: number;
      rejected_count: number;
      rejections: Rejection[];
      latency_ms: number | null;
      model_hash: string | null;
      consensus: ConsensusSummary;
    }
  | ({ type: "seed_done" } & SeedDone)
  | { type: "done"; results: SeedDone[]; source: string }
  | { type: "error"; message: string };
export type RunEventType = RunEvent["type"];

export type ResultName =
  | "scenarios"
  | "scenarios_curves"
  | "rejections"
  | "baseline"
  | "phase2_fl"
  | "phase3_fl"
  | "sig_bench"
  | "sig_bench_overhead"
  | "sig_bench_throughput"
  | "zk_bench"
  | "zk_consensus"
  | "overheads"
  | "attack_matrix";


// ---- hand-written: /api/overheads has no response model in the backend ----------------------------
export interface Table {
  source: string;
  rows: Row[];
}
export interface OverheadsResponse {
  hardware: Hardware;
  signatures: Table;
  envelope: Table;
  throughput: Table;
  zk: Table;
  /** Shape is only partly specified ("per attack/defence"); rendered defensively. */
  round: { source: string; rows?: Row[]; [key: string]: unknown };
  markdown: { source: string; text: string };
}
